import fs from 'node:fs';
import path from 'node:path';

async function check(url) {
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(5000) });
    const text = await res.text().catch(() => '');
    return { ok: res.ok, status: res.status, contentType: res.headers.get('content-type') || '', sample: text.slice(0, 240) };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

async function checkAlphaFrontend(baseUrl) {
  try {
    const res = await fetch(`${baseUrl}/src/Workspace.tsx`, { signal: AbortSignal.timeout(5000) });
    const text = await res.text().catch(() => '');
    const contentType = res.headers.get('content-type') || '';
    const ok = Boolean(res.ok && !text.trimStart().startsWith('<!DOCTYPE html>') && /AlphaLab|Workstation|Dockview|ModeSidebar|RightRail/i.test(text));
    return { ok, status: res.status, contentType, sample: text.slice(0, 240) };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

export async function run(input = {}) {
  const projectRoot = input.projectRoot || 'E:\\quant-framework';
  const stateFile = path.join(projectRoot, '.conexus', 'alphalab-runner', 'state.json');
  let state = {};
  if (fs.existsSync(stateFile)) state = JSON.parse(fs.readFileSync(stateFile, 'utf8'));
  const backendPort = Number(input.backendPort || state.backendPort || 8000);
  const frontendPort = Number(state.frontendPort || input.frontendPort || 5173);
  const urls = {
    backend: `http://127.0.0.1:${backendPort}/`,
    docs: `http://127.0.0.1:${backendPort}/docs`,
    frontend: `http://localhost:${frontendPort}/`,
    frontendSourceProbe: `http://localhost:${frontendPort}/src/Workspace.tsx`
  };
  const backend = await check(urls.backend);
  const docs = await check(urls.docs);
  const frontend = await check(urls.frontend);
  const frontendSourceProbe = await checkAlphaFrontend(`http://localhost:${frontendPort}`);
  return { ok: Boolean(backend.ok && docs.ok && frontend.ok && frontendSourceProbe.ok), urls, backend, docs, frontend, frontendSourceProbe, stateFile };
}
